BEGIN READ ONLY;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
SELECT jsonb_build_object(
 'captured_at',clock_timestamp(),
 'strict_schema_exists',to_regnamespace('comparator_strict') IS NOT NULL,
 'client_connections',(SELECT count(*) FROM pg_stat_activity WHERE backend_type='client backend' AND pid<>pg_backend_pid()),
 'blocked',(SELECT count(*) FROM pg_stat_activity WHERE pid<>pg_backend_pid() AND cardinality(pg_blocking_pids(pid))>0),
 'active_older_30s',(SELECT count(*) FROM pg_stat_activity WHERE state='active' AND query_start<now()-interval '30 seconds' AND pid<>pg_backend_pid()),
 'legacy_functions',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'hash',md5(pg_get_functiondef(p.oid)))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','private','comparator_internal') AND p.proname IN ('catalog_cheaper_products_v7','catalog_finalize_embedding_batch','catalog_dispatch_embedding_jobs','claim_free_comparator_use')),
 'unmapped_migrations',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',cardinality(statements),'bytes',octet_length(array_to_string(statements,E'\n')),'hash',md5(array_to_string(statements,E'\n')))) FROM supabase_migrations.schema_migrations WHERE version IN ('20260823194414','20260824172919')),
 'extensions',(SELECT jsonb_agg(jsonb_build_object('name',name,'installed',installed_version,'available',default_version)) FROM pg_available_extensions WHERE name IN ('pgtap','pg_jsonschema')),
 'default_privileges',(SELECT jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(defaclrole),'schema',n.nspname,'type',defaclobjtype,'acl',defaclacl::text)) FROM pg_default_acl a LEFT JOIN pg_namespace n ON n.oid=a.defaclnamespace WHERE defaclrole=(SELECT oid FROM pg_roles WHERE rolname=current_user))
) AS evidence;
ROLLBACK;

BEGIN READ ONLY; SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
