BEGIN READ ONLY; SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $test$
DECLARE client_role text; object_name text; denied boolean;
BEGIN
FOREACH client_role IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
 FOREACH object_name IN ARRAY ARRAY['execution_control','execution_jobs','execution_budget','test_principals'] LOOP
  EXECUTE format('SET LOCAL ROLE %I',client_role); denied:=false;
  BEGIN EXECUTE format('SELECT 1 FROM comparator_strict.%I LIMIT 1',object_name);
  EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
  RESET ROLE;
  IF NOT denied THEN RAISE EXCEPTION 'Unexpected accessible table % for %',object_name,client_role; END IF;
 END LOOP;
END LOOP;
END $test$;
SELECT jsonb_build_object('captured_at',now(),'role_denials_passed',12,'health',jsonb_build_object(
'connections',(SELECT count(*) FROM pg_stat_activity WHERE backend_type='client backend' AND pid<>pg_backend_pid()),
'blocked',(SELECT count(*) FROM pg_stat_activity WHERE wait_event_type='Lock' AND pid<>pg_backend_pid()),
'active_older_30s',(SELECT count(*) FROM pg_stat_activity WHERE state='active' AND query_start<now()-interval '30 seconds' AND pid<>pg_backend_pid()))) evidence;
ROLLBACK;

